import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { SidsService } from 'src/app/services/emis/sids.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-inspection-selection',
  templateUrl: './inspection-selection.page.html',
  styleUrls: ['./inspection-selection.page.scss'],
})
export class InspectionSelectionPage implements OnInit {

  form: FormGroup;
  noData: boolean;
  udiseLen: any;
  udise: any;
  simple : boolean;
  public isOnline: boolean = false; 
  sessionUserName: any;
  allSidsData: any[];
  searchTerm: any;
  searchData: any = [];

  constructor(private fb: FormBuilder, private userService: UserService,
    private router: Router, private sidsService: SidsService,
    private usersessionService: UserSessionService ,) { }

  ngOnInit() {

  }

  ionViewDidEnter() { 
    this.sessionUserName = this.usersessionService.emis_username();
    this.getSIDSInfo()
  }

  getSIDSInfo() {
    this.allSidsData = []
  this.sidsService.SecSidsVisitDetails(this.sessionUserName).subscribe((res) => {
    this.allSidsData = res.result
    this.searchData = this.allSidsData;
    console.log(res.result,"123", this.allSidsData)
  });
} 

getSearch(event){
  this.allSidsData = [];
  this.searchTerm = event.detail.value.trim();
  this.allSidsData = this.searchData.filter((item) => {
    return item.SchlName.toLowerCase().indexOf(this.searchTerm.toLowerCase()) > -1;
  });
}

  nextPage(id) {
    // this.router.navigate(['/tabs/my-inspection-sids'], { queryParams: { 'Id': id }, skipLocationChange: false });
  }

  onBack() {
    this.router.navigate(['/tabs/dashboard'])  
  }

}
